<script setup>
import {computed,ref} from 'vue';
import {onBeforeRouteLeave} from 'vue-router';
import {createClientInfoReader} from '../../api/client-info';
import {detectPhones,cleanMobile} from '../../lib/client-info';
import {normalizeClientMobile,clientContactSchema,clientNumberOwners,saveClientContact} from '../../lib/client-contacts';
const props=defineProps({bundle:Object});const emit=defineEmits(['busy']);
const mobile=ref(''),busy=ref(false),notice=ref(''),error=ref(''),checked=ref(''),owners=ref([]),schema=ref(null),related=ref(''),relationship=ref('');
const relations=computed(()=>schema.value?.relation?.fieldtype==='Select'?String(schema.value.relation.options||'').split('\n').filter(Boolean):['Spouse','Parent','Child','Sibling','Other']);
async function check(){if(busy.value)return;busy.value=true;error.value='';notice.value='Checking existing client numbers…';checked.value='';owners.value=[];try{const n=normalizeClientMobile(mobile.value),sc=await clientContactSchema(createClientInfoReader());if(detectPhones(props.bundle.patient).some(p=>cleanMobile(p.number).slice(-10)===n))throw Error('This number is already listed for this client.');const matches=await clientNumberOwners(createClientInfoReader(),n,sc);if(matches.some(p=>p.name===props.bundle.pid))throw Error('This number is already listed for this client.');const others=matches.filter(p=>p.name!==props.bundle.pid);if(others.length&&(!sc.family||!sc.linked||!sc.relation))throw Error('This number belongs to another client. The relationship fields are unavailable; it cannot be added as an alternative number.');schema.value=sc;owners.value=others;related.value=others[0]?.name||'';relationship.value='';checked.value=n;notice.value=others.length?'This number belongs to an existing client. Link the person under a relationship instead of copying their number.':'Number is available.';}catch(e){error.value=e.message;notice.value='';}finally{busy.value=false;}}
async function save(){if(busy.value)return;try{if(normalizeClientMobile(mobile.value)!==checked.value)throw Error('Number changed. Check the number again.');}catch(e){error.value=e.message;return;}busy.value=true;emit('busy',true);error.value='';try{const doc=await saveClientContact(createClientInfoReader(),props.bundle,checked.value,schema.value,owners.value.length?related.value:'',relationship.value);Object.assign(props.bundle.patient,doc);checked.value='';mobile.value='';notice.value=owners.value.length?'Relationship linked.':'Alternative number saved.';}catch(e){error.value=e.message;}finally{busy.value=false;emit('busy',false);}}
onBeforeRouteLeave(()=>!busy.value);
</script>
<template><details class="c3-contact-edit"><summary class="c3-btn">＋ Add alternative number</summary><form data-alt-form @submit.prevent="check"><label>Mobile number<input v-model="mobile" class="c3-input" name="mobile" inputmode="tel" autocomplete="off" placeholder="10-digit mobile or +91" required :disabled="busy" @input="checked='' "></label><button class="c3-btn" type="submit" :disabled="busy">Check number</button><div data-alt-result role="status"><p>{{notice}}</p><p v-if="error" role="alert">{{error}}</p><template v-if="checked"><template v-if="owners.length"><label>Related client<select v-model="related" class="c3-input" data-related><option v-for="p in owners" :key="p.name" :value="p.name">{{p.patient_name||p.name}}</option></select></label><label>Relationship<select v-model="relationship" class="c3-input" data-relation><option value="">Select relationship</option><option v-for="r in relations" :key="r">{{r}}</option></select></label></template><button type="button" class="c3-btn" :disabled="busy" @click="save">{{owners.length?'Link relationship':'Save alternative number'}}</button></template></div></form></details></template>
